text:
Το παρακάτω συμβόλαιο επιτρέπει σε έναν ιδιοκτήτη να πουλήσει ένα πατίνι και σε έναν αγοραστή να το αγοράσει. Η τιμή είναι 1000 μονάδες του token ERC-20 που ονομάζεται «Token», το οποίο υποτίθεται ότι έχει πραγματική αξία. Η πώληση ολοκληρώνεται μόνο όταν ο αγοραστής μεταφέρει το συμφωνημένο ποσό στον πωλητή.

```solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract Patinaki {
    address public owner;
    address public buyer;
    address public seller;
    uint256 public price;
    uint256 public sold;

    event PatinakiSold(address indexed buyer, address indexed seller);

    constructor() {
        owner = msg.sender;
        buyer = address(0);
        seller = address(0);
        price = 1000;
        sold = 0;
    }

    function sellPatinaki(address _seller) public {
        require(msg.sender == owner, "Only owner can sell");
        seller = _seller;
        buyer = msg.sender;
    }

    function buyPatinaki() public payable {
        require(msg.value == price, "Incorrect payment");
        require(buyer == msg.sender, "Only buyer can buy");
        require(seller != address(0), "Patinaki not for sale");
        require(!sold, "Patinaki already sold");
        sold = 1;
        emit PatinakiSold(buyer, seller);
    }
}
```

Το συμβόλαιο ορίζει τον ιδιοκτήτη, τον αγοραστή, τον πωλητή, την τιμή, τον αριθμό των πωλημένων πατινιών και ένα γεγονός όταν ολοκληρωθεί η πώληση. Η πώληση ενεργοποιείται μόνο όταν ο ιδιοκτήτης ορίσει τον πωλητή και ο αγοραστής πληρώσει ακριβώς 1000 μονάδες του token. Η πώληση ολοκληρώνεται όταν ο αγοραστής μεταφέρει το ποσό και το συμβόλαιο εκδίδει το γεγονός.

